// H5 fix: invoice.pay() is synchronous — a missing PI ID means we cannot track the
// payment or confirm the deposit SAGA. Throw instead of lying to callers with a
// fallback invoiceId. The reaper cron will clean up the deposit SAGA if this fires.
const invoicePiId = invoiceResult.paymentIntentId
if (!invoicePiId) {
  throw new Error(
    'createSessionPaymentIntent (invoice path): Stripe returned no PaymentIntent ID after invoice.pay(). Cannot proceed.',
  )
}

// H12 / C4 fix: Patch the internally-created invoice PI's metadata so the
// payment_intent.succeeded webhook handler can confirm the deposit SAGA step
// (CONFIRM_DEPOSIT_APPLICATION). Stripe does NOT copy invoice metadata to the PI.
// Without this patch, depositTransactionId is missing from the PI → SAGA never
// confirms → deposit stuck in pending_apply → reaper cleans it up → pool drift.
// Metadata updates are idempotent by nature; no withIdempotencyKey wrapper needed.
if (depositTransactionId) {
  const stripe = getStripe()
  await stripe.paymentIntents.update(
    invoicePiId,
    {
      metadata: {
        inkos_deposit_transaction_id: depositTransactionId,
        inkos_tip_destination: tipDestination,
        inkos_tip_pool_enabled: String(args.tipPoolEnabled),
        inkos_studio_id: args.studioId,
        inkos_session_id: args.sessionId,
        inkos_artist_id: args.artistId,
      },
    },
  )
}

const { error: chargeRecErr } = await supabase.rpc(RPC.STRIPE_CHARGE_RECORD, {
  p_studio_id: args.studioId,
  p_payment_intent_id: invoicePiId,
  p_status: (invoiceResult.paymentIntentStatus ?? 'processing') as StripeChargeStatus,
  p_currency: args.currency,
  p_amount_cents: invoiceResult.totalCents,
  p_tax_amount_cents: invoiceResult.taxAmountCents,
  p_application_fee_cents: effectiveApplicationFee,
  p_net_artist_cents: netArtistCents,
  p_tip_amount_cents: args.tipAmountCents,
  p_booking_id: args.bookingId,
  p_project_id: args.projectId,
  p_session_id: args.sessionId,
  p_client_id: args.clientId,
  p_deposit_drawdown_cents: args.depositDrawdownCents,
  p_idempotency_key: piIdemKey,
  p_presentment_currency: null,
  p_presentment_amount_cents: null,
})
if (chargeRecErr) {
  logger.error(
    { invoice_id: invoiceResult.invoiceId, err: chargeRecErr },
    'CRITICAL: stripe_charge_record failed after invoice pay — rethrowing for retry',
  )
  throw chargeRecErr
}

logger.info({
  studio_id: args.studioId,
  session_id: args.sessionId,
  invoice_id: invoiceResult.invoiceId,
  payment_intent_id: invoicePiId,
  idempotency_key: piIdemKey,
  duration_ms: Date.now() - startedAt,
}, 'session invoice created (tax registration active)')

return {
  paymentIntentId: invoicePiId,
  clientSecret: null,
  status: invoiceResult.paymentIntentStatus ?? 'processing',
  depositTransactionId,
  amountChargedCents,
}
